import {randomUUID} from 'node:crypto';
export function sourcePaperFixture(){const entry=randomUUID();return {schemaVersion:1,layout:{template:'miaoda-paper',fontSize:12,identityPosition:'top',identityNameAlignment:'center'},sections:[{id:randomUUID(),kind:'skills',title:'专业技能',blocks:[{id:randomUUID(),type:'paragraph',spans:[{text:'TEST 中文技能',marks:[{type:'bold'}]}]}]},{id:randomUUID(),kind:'project',title:'项目经历',blocks:[...['name','responsibility','date'].map((field,index)=>({id:randomUUID(),type:'paragraph',entry:{id:entry,field},spans:index===0?[{text:'TEST 项目',marks:[]}]:[]})),{id:randomUUID(),type:'bullet-list',items:[{id:randomUUID(),paragraphId:randomUUID(),spans:[{text:'TEST 负责交付',marks:[{type:'italic'}]}]}]}]}]};}
